            const size_t offset = static_cast<size_t>(raw - base);
            if (offset % stride != 0) [[unlikely]]
            {
                return false;
            }

            // 3. 映射到具体槽位
            const size_t index = offset / stride;
            Slot &slot = slots_[index];

            // 4. 重复释放校验：已被归还的槽位不可再次归还
            if (!slot.inUse) [[unlikely]]
