        /**
         * @brief 获取当前未被借出的空闲对象数量
         */
        [[nodiscard]] inline size_t available() const noexcept { return freeCount_; }

    private:
        struct Slot
        {
            Object object{};
            bool inUse{false};
        };

        std::unique_ptr<Slot[]> slots_{nullptr};
        std::unique_ptr<size_t[]> freeStack_{nullptr}; // 固定容量 = capacity_，逆序初始（低地址优先借出）
