         *       writableBytes() >= n——直接写窗口请走 ensureWritable()。
         *
         * @return 成功 {}；堆扩容失败 std::unexpected(ERR::BUF_ALLOC_FAILED)
         */
        [[nodiscard]] inline Result<> reserve(size_t n) noexcept
        {
            return grow(n) ? Result<>{} : std::unexpected(ERR::BUF_ALLOC_FAILED);
        }

        /**
