         * @return 成功 {}；堆扩容失败 std::unexpected(ERR::BUF_ALLOC_FAILED)
         */
        [[nodiscard]] inline Result<> ensureWritable(size_t n) noexcept
        {
            if (writableBytes() >= n) [[likely]]
            {
                return {};
